<script setup lang="ts">
import {computed,ref,watch,onUnmounted,nextTick} from 'vue';
import {BookOpen,ArrowRight,ShieldCheck,Upload,Download,Search,X,Play,Blocks,ExternalLink} from 'lucide-vue-next';
import {useDesktop} from '../useDesktop';
import {invoke} from '../bridge';
import {trapModalFocus} from '../modalFocus';
import type {PresetEntry,Room} from '../../types';
const d=useDesktop();const {state}=d;const instanceId=ref(''),entries=ref<PresetEntry[]>([]),search=ref(''),filter=ref('all'),error=ref(''),loading=ref(false),working=ref(false),selected=ref<PresetEntry|null>(null),title=ref(''),requestKey=ref(''),dialog=ref<HTMLElement|null>(null);
const instance=computed(()=>state.value.instances.find(i=>i.id===instanceId.value)),running=computed(()=>instance.value?.status==='running');
const shown=computed(()=>entries.value.filter(p=>(p.name+' '+p.description+' '+(p.tags||[]).join(' ')).toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='all'||filter.value==='ready'&&p.compatibility.can_create||filter.value==='imported'&&p.source!=='bundled')));
let epoch=0,disposed=false;let releaseFocus:(()=>void)|undefined;
async function load(){const target=instanceId.value,token=++epoch;entries.value=[];error.value='';if(!target||!running.value)return;loading.value=true;try{const result=await invoke<{entries:PresetEntry[]}>('presetCatalog',{instanceId:target});if(!disposed&&epoch===token)entries.value=result.entries;}catch(e:any){if(epoch===token)error.value=e.message;}finally{if(epoch===token)loading.value=false;}}
watch(()=>state.value.instances,values=>{if(!instanceId.value)instanceId.value=values.find(i=>i.status==='running')?.id||'';},{immediate:true});
watch([instanceId,()=>instance.value?.status],()=>{void load();close();},{immediate:true});
function close(){if(working.value)return;releaseFocus?.();releaseFocus=undefined;selected.value=null;}
async function preview(preset:PresetEntry){selected.value=preset;title.value=preset.name;requestKey.value=crypto.randomUUID().replaceAll('-','');await nextTick();if(dialog.value)releaseFocus=trapModalFocus(dialog.value,close);}
async function action(fn:()=>Promise<void>){if(working.value)return;working.value=true;error.value='';try{await fn();}catch(e:any){error.value=e.message;}finally{working.value=false;}}
function importData(){const target=instanceId.value;void action(async()=>{const result=await invoke('importPreset',{instanceId:target});if(!result.cancelled){await load();d.flash('数据作品已导入本机库，可预览后开新房间。已有房间与内容锁保留。');}});}
function exportData(){if(!selected.value)return;const hash=selected.value.package_hash;void action(async()=>{const result=await invoke('exportPreset',{instanceId:instanceId.value,packageHash:hash});if(result.exported)d.flash('完整数据作品已保存。分享前检查主持秘密和各组件许可。');});}
function create(){if(!selected.value)return;const target=instance.value,hash=selected.value.package_hash,name=title.value,key=requestKey.value;if(!target)return;void action(async()=>{const room=await invoke<Room>('createPresetRoom',{instanceId:target.id,packageHash:hash,title:name,requestKey:key,hostPlays:true});if(disposed)return;d.rememberRoom(target.id,room);releaseFocus?.();releaseFocus=undefined;selected.value=null;await d.refresh();await d.enter(target,'setup');d.flash('整套玩法已创建为新冒险，精确内容与模块版本已锁定。');});}
onUnmounted(()=>{disposed=true;epoch++;releaseFocus?.();});
</script>
<template><main class="global-workspace"><div class="page-intro"><span class="eyebrow">WORLDS WAITING TO BE OPENED</span><h1>内容库</h1><p>先预览玩法、署名和兼容性，再开启一场新冒险。每间酒馆保留自己的作品版本。</p></div>
 <section class="panel library-controls"><label>查看酒馆<select v-model="instanceId" :disabled="working" aria-label="内容库酒馆"><option value="">选择运行中的酒馆</option><option v-for="i in state.instances" :key="i.id" :value="i.id" :disabled="i.status!=='running'">{{i.name}} · {{d.statusLabel[i.status]}}</option></select></label><button class="secondary" :disabled="!running||working||loading||!d.native" @click="importData"><Upload :size="16"/>导入数据作品</button><button class="text-button" :disabled="!running||working||loading" @click="load">刷新作品</button></section>
 <p v-if="error" class="warning" role="alert">{{error}}</p><section v-if="!running" class="empty"><BookOpen :size="32"/><h3>先准备一间酒馆</h3><p>启动酒馆后，可校验玩法兼容性、导入作品并开桌。</p><button class="primary" @click="d.navigate('home')">返回首页 <ArrowRight :size="16"/></button></section>
 <template v-else><label class="dashboard-search library-search"><Search :size="18"/><input v-model="search" aria-label="搜索玩法预设" placeholder="搜索玩法、题材与标签…"/></label><div class="filter-tabs"><button v-for="item in [['all','全部作品'],['ready','可直接开桌'],['imported','我的导入']]" :key="item[0]" :class="{active:filter===item[0]}" @click="filter=item[0]">{{item[1]}}</button></div><p v-if="loading" role="status" class="help-text">正在读取本机作品与精确依赖状态…</p><section v-else-if="!shown.length" class="empty"><BookOpen :size="30"/><h3>暂无匹配作品</h3><p>可导入自己的数据包，或修改搜索与筛选条件。</p></section><section class="content-grid"><button v-for="preset in shown" :key="preset.package_hash" class="panel content-card" @click="preview(preset)"><div class="panel-title"><BookOpen :size="23"/><span :class="['badge',{warning:!preset.compatibility.can_create}]">{{preset.compatibility.can_create?'可以开桌':'需要处理依赖'}}</span></div><h3>{{preset.name}}</h3><p>{{preset.description||'完整数据玩法预设'}}</p><div class="content-meta"><span>{{preset.min_players}}–{{preset.max_players}} 人</span><span>{{preset.duration_minutes}} 分钟</span><span>{{preset.character_count}} 位角色</span></div><footer><span>{{preset.source==='bundled'?'随本体提供':'本机导入'}} · v{{preset.version}}</span><ArrowRight :size="16"/></footer></button></section></template>
 <div class="notice"><ShieldCheck :size="18"/><p>数据导入不会执行代码或改写已有房间的内容锁。缺少模块时，先在对应酒馆停止服务、审阅安装和授权，再刷新兼容性。</p></div><section class="panel author-entry"><h3>创作与发布</h3><p class="help-text">作者 SDK 提供脚手架、校验、不可变打包和投稿材料检查。目录审核与 SHA256 不授予 Python 执行信任；作品许可与真实来源需由作者确认。</p><div class="row"><button class="text-button" @click="d.act('external',{url:'https://github.com/Tera-Dark/Ember-Tavern/blob/main/docs/CREATOR_GUIDE.md'})"><ExternalLink :size="15"/>打开作者流程</button><button class="text-button" @click="d.act('external',{url:'https://github.com/Tera-Dark/Ember-Tavern/blob/main/docs/COMMUNITY_REVIEW.md'})">投稿与目录审阅</button><button v-if="instance" class="text-button" @click="d.enter(instance,'plugins')"><Blocks :size="15"/>查看实例模块</button></div></section>
</main>
<Teleport to="body"><div v-if="selected" class="overlay"><section ref="dialog" class="dialog preset-preview" role="dialog" aria-modal="true" aria-label="玩法预设详情"><button class="dialog-close" aria-label="关闭作品详情" :disabled="working" @click="close"><X :size="20"/></button><span class="eyebrow">EXACT EDITION</span><h2>{{selected.name}}</h2><p>{{selected.description}}</p><dl class="settings-summary"><div><dt>作者</dt><dd>{{selected.authors?.join('、')||'未声明'}}</dd></div><div><dt>许可</dt><dd>{{selected.license||'未声明，分享前确认'}}</dd></div><div><dt>规则</dt><dd>{{selected.rule_system||'查看作品清单'}} · 最低宿主 {{selected.minimum_host||'未声明'}}</dd></div><div><dt>版本</dt><dd>{{selected.version}} · {{selected.source==='bundled'?'随本体提供':'本机导入'}}</dd></div></dl><details><summary>精确版本与模块依赖</summary><code class="content-hash">{{selected.package_hash}}</code><p v-for="pin in selected.plugins||[]" :key="pin.id" class="help-text">{{pin.id}} · {{pin.version}} · {{pin.required?'必需':'可选'}} · {{pin.enabled?'开桌启用':'默认关闭'}}<code class="content-hash">{{pin.sha256}}</code></p></details><p v-for="notice in selected.content_warnings||[]" :key="notice" class="warning">内容提醒：{{notice}}</p><p v-for="notice in [...selected.warnings||[],...selected.compatibility.warnings]" :key="notice" class="help-text">{{notice}}</p><p v-for="blocker in selected.compatibility.blockers" :key="blocker" class="warning">{{blocker}}</p><label class="form">新冒险名称<input v-model="title" maxlength="60" :disabled="working" aria-label="内容库新冒险名称"/></label><p class="help-text">创建新房间、默认演示主持并锁定此版本，不覆盖旧房间。导出包含完整作品，可能带主持秘密；分享前核对许可。</p><p v-if="error" class="warning" role="alert">{{error}}</p><div class="row"><button class="secondary" :disabled="working||!running||!d.native" @click="exportData"><Download :size="16"/>导出完整作品</button><button class="primary" :disabled="working||!running||!selected.compatibility.can_create||!title.trim()" @click="create"><Play :size="15"/>{{working?'正在处理…':'以此版本开新桌'}}</button></div></section></div></Teleport>
</template>
